declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;use App\Services\ProjectionSettingsService;use App\Services\ProjectionLayoutService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$s=LiveDisplaySessionService::byToken($pdo,$token);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');header('Pragma: no-cache');if(!$s){http_response_code(404);echo json_encode(['ok'=>false]);exit;}$test=$s['data_mode']==='test';$eventTable=$test?'bdc_test_events':'bdc_events';$entryTable=$test?'bdc_test_scoring_entries':'bdc_scoring_entries';$e=$pdo->prepare("SELECT name FROM {$eventTable} WHERE id=:id");$e->execute(['id'=>$s['event_id']]);$eventName=(string)($e->fetchColumn()?:'BDC Event');$roundId=(int)($s['current_round_id']??0);$total=1;if($roundId&&in_array($s['screen_type'],['competitors','callbacks','finalists'],true)){$count=0;if($s['screen_type']==='competitors'){$q=$pdo->prepare("SELECT COUNT(*) FROM {$entryTable} WHERE round_id=:r AND entry_status='active'");$q->execute(['r'=>$roundId]);$count=(int)$q->fetchColumn();}else{$resultTable=$test?'bdc_test_scoring_results':'bdc_scoring_results';$q=$pdo->prepare("SELECT COUNT(*) FROM {$resultTable} WHERE round_id=:r AND result_status IN('callback','alternate')");$q->execute(['r'=>$roundId]);$count=(int)$q->fetchColumn();}$set=ProjectionSettingsService::get($pdo,$roundId,$test);$layout=ProjectionLayoutService::resolve((string)$set['screen_format'],max(1,$count),(string)$set['density'],$set['custom_width']?:null,$set['custom_height']?:null);$total=max(1,(int)$layout['pages']);}echo json_encode(['ok'=>true,'event_name'=>$eventName,'round_id'=>$roundId,'screen_type'=>$s['screen_type'],'reveal_place'=>$s['reveal_place']??null,'page_number'=>(int)$s['page_number'],'total_pages'=>$total,'auto_page'=>(bool)$s['auto_page'],'page_delay_seconds'=>(int)$s['page_delay_seconds'],'state_version'=>(int)$s['state_version']],JSON_UNESCAPED_SLASHES);